/// <summary>
/// PaffH 18.07.23
/// get contracts with PA label administrated
/// </summary>
class NDXBatchJobPALabelAdministrated
    extends NDXBatchJobPALabel

{
}

Method.Source:
/// <summary>
/// PaffH 18.07.23
/// </summary>
/// <param name = "_batchJobId">RecId</param>
/// <returns>NDXBatchJobPALabelAdministrated</returns>
static NDXBatchJobPALabelAdministrated construct(RecId _batchJobId = 0)
{
    NDXBatchJobPALabelAdministrated nDXBatchJobPALabelAdministrated = new NDXBatchJobPALabelAdministrated(_batchJobId);
    BatchHeader batchHeader = nDXBatchJobPALabelAdministrated.parmBatchHeader();
    if (batchHeader.parmBatchGroup() != batchGroupId)
    {
        batchHeader.parmBatchGroup(nDXBatchJobPALabelAdministrated.parmBatchGroup(batchGroupId, batchGroupIdDescription).Group);
    }
    return nDXBatchJobPALabelAdministrated;
}

/// <summary>
/// PaffH 20.07.23
/// </summary>
/// <param name = "_args">Args</param>
/// <returns>RefRecId</returns>
public RefRecId addTask(Args _args = new Args())
{

    NDXPALabelAdministratedController controller = NDXPALabelAdministratedController::construct(_args);

    NDXPALabelAdministratedContract contract = controller.getDataContractObject('_contract');
    if (!contract)
    {
        // Function %1 was called with an invalid value
        throw Error(strFmt("@SYS23264", classStr(NDXPALabelAdministratedContract)));
    }

    SysRecurrenceData sysRecurrenceData = SysRecurrence::defaultRecurrence();
    sysRecurrenceData = SysRecurrence::setRecurrenceStartDateTime(sysRecurrenceData, DateTimeUtil::addHours(DateTimeUtil::utcNow(), 1));
    sysRecurrenceData = SysRecurrence::setRecurrenceNoEnd(sysRecurrenceData);
    sysRecurrenceData = SysRecurrence::setRecurrenceUnit(sysRecurrenceData, SysRecurrenceUnit::Minute, 10);
    batchHeader.parmRecurrenceData(sysRecurrenceData);

    batchHeader.parmCaption("@NDX:NDXClassDescriptionNDXBatchJobPALabelMaintained");
    batchHeader.parmStartDateTime(DateTimeUtil::addHours(DateTimeUtil::utcNow(), 1));    // job shouldn't start immediately
    batchHeader.parmLogLevel(BatchLogLevel::Always);
    batchHeader.parmExecutingBy(#AdminUser);

    controller.parmDialogCaption(batchHeader.parmCaption());
    batchHeader.addTask(controller);
    batchHeader.save();

    return batchHeader.parmBatchHeaderId();
}

/// <summary>
/// PaffH 20.07.23
/// </summary>
/// <returns>ClassDescription</returns>
client server static ClassDescription description()
{
    return "@NDX:NDXClassDescriptionNDXBatchJobPALabelMaintained";
}
